// Potion appearances are derived from their effects, not from their names or rarity.
const POTION_LOOK={heal:['selfValue','#e65e64'],strength:['selfStatus','#e6a755'],agility:['selfStatus','#98bfd7'],guard:['selfValue','#4d9ee5'],draw:['selfValue','#e5c26b'],energy:['selfValue','#f1dd54'],creation:['selfValue','#b895e3'],poison:['enemyStatus','#73c857'],fire:['enemyDamage','#ef8052'],blast:['allDamage','#f2af53']};
function potionBottle(p){const [kind,color]=POTION_LOOK[p.id]||['selfValue','#c6bd99'];const shapes={selfStatus:'M25 9H39V19L47 27V51Q47 56 42 56H22Q17 56 17 51V27L25 19Z',selfValue:'M26 9H38V19Q50 25 50 41Q50 56 32 57Q14 56 14 41Q14 25 26 19Z',enemyStatus:'M25 9H39V19L51 50Q53 57 46 57H18Q11 57 13 50L25 19Z',enemyDamage:'M25 9H39V19L49 29V47L32 58 15 47V29L25 19Z',allDamage:'M25 9H39V18L48 23 55 37 48 52 32 58 16 52 9 37 16 23 25 18Z'};return `<svg class="potion-bottle" viewBox="0 0 64 64" aria-hidden="true"><path d="M24 7H40V12H24Z" fill="#a98e69"/><path d="${shapes[kind]}" fill="${color}" fill-opacity=".76" stroke="#e5d5b1" stroke-width="2.4" stroke-linejoin="round"/><path d="M23 31Q27 28 31 30" fill="none" stroke="#fff" opacity=".5" stroke-width="2.3" stroke-linecap="round"/></svg>`;}
for(const p of POTIONS)p.icon=potionBottle(p);
function relicEffectIcon(e){return ({journey:'⌁',opening:'◷',combat:'⚔',energy:'✦',status:'✚',cards:'▣'})[e.cat]||'◇';}
function relicEffectText(e){const p=POTIONS.find(x=>x.id===e.potion);if(!p)return escapeHTML(e.text);return escapeHTML(e.text).replace(escapeHTML(p.name),`<span class="status-help potion-term" tabindex="0"><strong class="keyword">${escapeHTML(p.name)}</strong><span class="tooltip"><strong>${escapeHTML(p.name)}</strong><br>${escapeHTML(p.desc)}</span></span>`);}
function toggleRelicEffectFilter(id,checked){if(!RELIC_BY_ID[id])return;relicEffectFilter=checked?[...new Set([...relicEffectFilter,id])]:relicEffectFilter.filter(x=>x!==id);render();document.querySelector('.relic-effect-filter')?.setAttribute('open','');}
function showExplorerDeckList(){if(S.run||page!=='characters')return;document.getElementById('explorer-deck-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='explorer-deck-dialog';dialog.setAttribute('aria-label','現在のデッキ一覧');dialog.innerHTML=`<div class="toolbar"><h2>現在のデッキ ${S.deck.length}枚</h2><form method="dialog"><button>閉じる</button></form></div><div class="explorer-deck-list">${[...new Set(S.deck)].sort(cardOrder).map(id=>card(id,'',`<span class="count">デッキ内 ×${count(id)}</span>`)).join('')}</div>`;dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);dialog.showModal();}
const home104=home;home=function(){let html=home104();const c=selectedCharacter();html=html.replace('</div><button class="primary" onclick="start()">','<small>探索者</small><button class="destination-home-button" onclick="page=\'characters\';render()"><span>'+c.icon+'</span><strong>'+c.name+'</strong><span>変更 ›</span></button></div><button class="primary" onclick="startSelectedCharacter()">').replace('探索者を選んで出発','探索に出る');return html.replace('<div class="hero-art">'+art()+'</div>','<div class="hero-art">'+destinationArt(chosenDestination().id)+'</div>');};
const INFO_STATUS_KEYS=['筋力','守護','ブロック','毒','再生','プレート','裂傷','脆弱','スタン','凍結','呪い','甲撃','呪い付与量','凍結付与量','鼓動'];
function infoCodexButtons(){return [['potions','ポーション'],['statuses','ステータス効果'],['keywords','キーワード']].map(([id,name])=>`<button class="${bookType===id?'primary':''}" onclick="bookType='${id}';render()">${name}</button>`).join('');}
function infoCodex(){let title,items;if(bookType==='potions'){title='ポーション';items=POTIONS.map(p=>({name:p.name,desc:p.desc,icon:p.icon}));}else{title=bookType==='statuses'?'ステータス効果':'キーワード';items=Object.entries(keywords).filter(([k,v])=>!!v&&(bookType!=='statuses'||INFO_STATUS_KEYS.includes(k))).map(([name,desc])=>({name,desc}));}return `<div class="eyebrow">GAME CODEX</div><h2>${title}の説明</h2><div class="toolbar"><button onclick="bookType='base';render()">基礎カード</button><button onclick="bookType='run';render()">潜在カード</button><button onclick="bookType='relics';render()">遺物</button>${infoCodexButtons()}</div><div class="tiles">${items.map(x=>`<article class="tile"><h3>${x.icon||''} ${escapeHTML(x.name)}</h3><p>${escapeHTML(x.desc)}</p></article>`).join('')}</div>`;}
const book104=book;book=function(){if(['potions','statuses','keywords'].includes(bookType))return infoCodex();const html=book104();return html.replace(/(<div class="toolbar"[^>]*>)([\s\S]*?)(<\/div>)/,(_,a,b,c)=>a+b+infoCodexButtons()+c);};
const render104=render;render=function(){render104();if(page==='battle'&&S.run){const list=document.querySelector('.battle-top .relic-list'),player=document.querySelector('.arena .unit[data-entity="player"]');if(list&&player)player.append(list);}};
if(!globalThis.ASHBOUND_HEADLESS)render();
